file.content:
/* Reset, typography and page layout. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-ink);
  background: var(--color-bg);
}

h1,
h2,
h3,
p,
ul,
ol,
dl,
dd,
figure {
  margin: 0;
}

ul,
ol {
  padding: 0;
  list-style: none;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: var(--color-brand);
}

[hidden] {
  display: none !important;
}

h1 {
  font-size: 36px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -0.02em;
}

h2 {
  font-size: 24px;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -0.01em;
}

h3 {
  font-size: 17px;
  line-height: 1.3;
  font-weight: 700;
}

.container {
  width: 100%;
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 0 var(--space-5);
}

.section {
  padding: var(--space-7) 0 0;
}

.section-title {
  margin-bottom: var(--space-5);
}

.page-head {
  padding-top: var(--space-7);
}

.page-head .lede {
  max-width: 640px;
  margin-top: var(--space-3);
}

.lede {
  font-size: 18px;
  color: var(--color-muted);
}

.muted {
  color: var(--color-muted);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  border: 0;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

@media (max-width: 720px) {
  h1 {
    font-size: 28px;
  }

  h2 {
    font-size: 21px;
  }

  .container {
    padding: 0 var(--space-4);
  }

  .section,
  .page-head {
    padding-top: var(--space-6);
  }
}

